import {snapshot,compare,reportJSON,reportCSV,LIMITS} from './core.js';
const $=id=>document.getElementById(id);
const state={before:null,after:null,report:null};const revisions={before:0,after:0};
function say(message){$('status').textContent=message;}
function invalidate(){state.report=null;$('results').hidden=true;$('rows').replaceChildren();$('summary').replaceChildren();$('compare').disabled=!(state.before?.ok&&state.after?.ok);}
function download(bytes,name,type){const url=URL.createObjectURL(new Blob([bytes],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function load(side,bytes,name,token){
 try{const result=await snapshot(bytes,name);if(token!==revisions[side])return;state[side]=result;$(side+'-status').textContent=result.ok?`${name} · ${result.rows.length} settings · ${result.source.bytes} bytes`:`${name} · review required`;
 $(side+'-original').disabled=false;invalidate();say(result.ok?'Snapshot loaded. Compare when both files are ready.':result.findings.map(f=>`${side}: ${f.row?'record '+f.row+' · ':''}${f.message}`).join('\n'));
 }catch(error){if(token!==revisions[side])return;state[side]=null;$(side+'-status').textContent='File could not be read';$(side+'-original').disabled=true;invalidate();say(`${side}: ${error.message}`);}
}
for(const side of ['before','after']){
 $(side).addEventListener('change',async event=>{const token=++revisions[side];state[side]=null;$(side+'-original').disabled=true;invalidate();const file=event.target.files[0];if(!file){$(side+'-status').textContent='No file selected';say('Selection cleared.');return;}$(side+'-status').textContent='Reading…';say('Reading snapshot…');try{if(file.size>LIMITS.bytes)throw new Error('File exceeds 250,000 bytes.');await load(side,new Uint8Array(await file.arrayBuffer()),file.name,token);}catch(error){if(token===revisions[side]){$(side+'-status').textContent='File could not be read';say(error.message);}}});
 $(side+'-original').addEventListener('click',()=>{const s=state[side];if(s)download(s.original,`rundelta-${side}-original.csv`,'text/csv');});
}
const syntheticBefore='parameter,value,unit,notes\ncell_id,SYN-014,,Synthetic specimen\ntemperature,25,°C,Chamber setpoint\nrest_duration,30,min,Before measurement\nsampling_interval,1,s,Acquisition\n';
const syntheticAfter='parameter,value,unit,notes\ncell_id,SYN-014,,Synthetic specimen\ntemperature,30,°C,Chamber setpoint\nrest_duration,1800,s,Before measurement\noperator_note,repeat,,Synthetic repeat\n';
$('example').addEventListener('click',async()=>{for(const side of ['before','after']){$(side).value='';state[side]=null;$(side+'-original').disabled=true;}invalidate();const a=++revisions.before,b=++revisions.after;await Promise.all([load('before',new TextEncoder().encode(syntheticBefore),'synthetic-before.csv',a),load('after',new TextEncoder().encode(syntheticAfter),'synthetic-after.csv',b)]);});
$('clear').addEventListener('click',()=>{for(const side of ['before','after']){revisions[side]++;state[side]=null;$(side).value='';$(side+'-status').textContent='No file selected';$(side+'-original').disabled=true;}invalidate();say('Workspace cleared. Choose two snapshots to begin.');});
function element(tag,text,className){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(className)e.className=className;return e;}
function valuesCell(data){const td=element('td');if(!data){td.textContent='Not present';return td;}for(const key of ['value','unit','notes']){const p=element('p');p.append(element('span',key.toUpperCase()+': ','label'),document.createTextNode(data[key]||'(empty)'));td.append(p);}return td;}
$('compare').addEventListener('click',()=>{if(!state.before?.ok||!state.after?.ok)return;state.report=compare(state.before,state.after);const r=state.report;$('summary').replaceChildren();for(const [key,label] of [['changed','Changed'],['added','Added'],['removed','Removed'],['unchanged','Unchanged'],['unitMismatches','Unit mismatches']]){const d=element('div',undefined,'metric');d.append(element('strong',r.counts[key]),element('span',label));$('summary').append(d);}$('rows').replaceChildren();for(const e of r.entries){const tr=element('tr');const name=element('th',e.parameter);name.scope='row';const status=element('td');status.append(element('span',e.status,'tag '+e.status));tr.append(name,status,valuesCell(e.before),valuesCell(e.after),element('td',e.unitMismatch?'Unit mismatch. Review before interpreting values.':e.changedFields.length?'Changed: '+e.changedFields.join(', '):e.status==='unchanged'?'Exact match':'Parameter '+e.status));$('rows').append(tr);}$('results').hidden=false;say(`Comparison complete. ${r.counts.changed} changed, ${r.counts.added} added, ${r.counts.removed} removed, ${r.counts.unchanged} unchanged.`);});
$('json').addEventListener('click',()=>{if(state.report)download(reportJSON(state.report),'rundelta-comparison.json','application/json');});
$('csv').addEventListener('click',()=>{if(state.report)download(reportCSV(state.report),'rundelta-comparison.csv','text/csv;charset=utf-8');});
